  "12-I-2#4": {"h": "Lợi nhuận là hàm bậc hai với hệ số âm, đạt lớn nhất tại đỉnh (hoặc nơi P'(x) = 0).", "y": ["P'(x) = 0 cho điểm cực đại duy nhất của hàm bậc hai có a < 0."], "b": ["P'(x) = −2x + 40 = 0 ⇔ x = 20.", "P(20) = −400 + 800 − 300 = 100.", "Đáp án: 100"]},
  "12-I-3#d": {"h": "Tiệm cận đứng của hàm phân thức là đường x = x₀ với x₀ làm mẫu bằng 0 mà tử khác 0.", "y": ["Đường x = x₀ là tiệm cận đứng nếu lim y = ±∞ khi x → x₀⁺ hoặc x → x₀⁻."], "b": ["Mẫu x − 1 = 0 ⇔ x = 1; tử tại x = 1 bằng 3 ≠ 0.", "Khi x → 1⁺ thì y → +∞, nên x = 1 là tiệm cận đứng.", "Đáp án: x = 1"]},
